/** Accessibility overlay: never changes the underlying app to open the menu. */
final class FloatingMenu {
 final AgentService service;final WindowManager wm;final Handler handler=new Handler();AgentBubble bubble;ProgressTicker ticker;boolean concealed;String lastTicker="";long tickerUntil;TextView detail;LinearLayout panel;ScrollView surface;EditText input;Button continueRun;ImageButton pauseRun,resumeRun;WindowManager.LayoutParams bubbleParams;String draft;boolean destroyed;
 final Runnable refresh=new Runnable(){public void run(){if(destroyed)return;bubble.state(service.running,service.paused);if(pauseRun!=null){pauseRun.setEnabled(service.running);pauseRun.setAlpha(service.running?1f:.3f);}if(resumeRun!=null){resumeRun.setEnabled(service.paused);resumeRun.setAlpha(service.paused?1f:.3f);}if(!lastTicker.equals(AgentService.liveText)){lastTicker=AgentService.liveText;tickerUntil=android.os.SystemClock.uptimeMillis()+8000;ticker.text(lastTicker);}ticker.setVisibility(!concealed&&!AgentService.appVisible&&(service.running||service.paused||android.os.SystemClock.uptimeMillis()<tickerUntil)?View.VISIBLE:View.INVISIBLE);if(continueRun!=null)continueRun.setVisibility(service.limitReached?View.VISIBLE:View.GONE);if(detail!=null)detail.setText((service.running?I18n.text(service,"running"):service.paused?I18n.text(service,"paused"):service.limitReached?I18n.text(service,"limit_reached"):I18n.text(service,"idle"))+" • Step "+service.step+"\n"+service.usage()+"\n"+AgentService.status.split("\n")[0]);handler.postDelayed(this,600);}};
 FloatingMenu(AgentService s){service=s;wm=(WindowManager)s.getSystemService(Context.WINDOW_SERVICE);draft=GoalSettings.goal(s);bubble=new AgentBubble(s);bubbleParams=new WindowManager.LayoutParams(dp(48),dp(48),WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);bubbleParams.gravity=Gravity.TOP|Gravity.LEFT;bubbleParams.x=s.getSharedPreferences("floating",0).getInt("x",dp(320));bubbleParams.y=s.getSharedPreferences("floating",0).getInt("y",dp(100));bubble.setOnTouchListener(new View.OnTouchListener(){float sx,sy;int ox,oy;boolean drag;public boolean onTouch(View v,android.view.MotionEvent e){switch(e.getAction()){case MotionEvent.ACTION_DOWN:sx=e.getRawX();sy=e.getRawY();ox=bubbleParams.x;oy=bubbleParams.y;drag=false;return true;case MotionEvent.ACTION_MOVE:float dx=e.getRawX()-sx,dy=e.getRawY()-sy;if(Math.hypot(dx,dy)>dp(8))drag=true;if(drag){android.graphics.Rect bounds=wm.getCurrentWindowMetrics().getBounds();bubbleParams.x=Math.max(0,Math.min(bounds.width()-bubble.getWidth(),ox+(int)dx));bubbleParams.y=Math.max(0,Math.min(bounds.height()-bubble.getHeight(),oy+(int)dy));wm.updateViewLayout(bubble,bubbleParams);}return true;case MotionEvent.ACTION_UP:if(!drag){v.performClick();open();}else service.getSharedPreferences("floating",0).edit().putInt("x",bubbleParams.x).putInt("y",bubbleParams.y).apply();return true;}return false;}});wm.addView(bubble,bubbleParams);ticker=new ProgressTicker(s);WindowManager.LayoutParams tp=new WindowManager.LayoutParams(wm.getCurrentWindowMetrics().getBounds().width()-dp(24),dp(38),WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE,PixelFormat.TRANSLUCENT);tp.gravity=Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL;tp.y=dp(12)+wm.getCurrentWindowMetrics().getWindowInsets().getInsets(WindowInsets.Type.navigationBars()).bottom;wm.addView(ticker,tp);handler.post(refresh);}
 int dp(int n){return (int)(n*service.getResources().getDisplayMetrics().density);}
 void open(){if(panel!=null){close();return;}panel=Ui.column(service);panel.setPadding(dp(20),dp(20),dp(20),dp(20));
  LinearLayout head=new LinearLayout(service);head.setGravity(Gravity.CENTER_VERTICAL);head.addView(Ui.mark(service,40));LinearLayout wordmark=Ui.column(service);wordmark.setPadding(dp(12),0,0,0);wordmark.addView(Ui.text(service,I18n.text(service,"app_name"),18,Ui.TEXT,true));head.addView(wordmark,new LinearLayout.LayoutParams(0,-2,1));Button dismiss=Ui.button(service,"×",false,this::close);dismiss.setTextSize(22);head.addView(dismiss,new LinearLayout.LayoutParams(dp(48),dp(48)));panel.addView(head);Ui.gap(panel,20);
  Ui.label(panel,"GOAL");input=Ui.input(service,GoalSettings.goal(service));GoalSettings.bind(input);input.setMinLines(2);input.setMaxLines(4);panel.addView(input);Ui.gap(panel,14);
  Button execute=Ui.button(service,I18n.text(service,"run_goal"),true,()->{String g=input.getText().toString();saveDraft();close();if(service.paused)service.stopGoal(I18n.text(service,"new_goal"));handler.postDelayed(()->service.startGoal(g),400);});LinearLayout actions=new LinearLayout(service);LinearLayout.LayoutParams executeParams=new LinearLayout.LayoutParams(0,dp(50),1);executeParams.rightMargin=dp(10);actions.addView(execute,executeParams);
  ImageButton voice=new ImageButton(service);voice.setImageResource(service.getResources().getIdentifier("ic_microphone","drawable",service.getPackageName()));voice.setScaleType(ImageView.ScaleType.CENTER_INSIDE);voice.setPadding(dp(13),dp(13),dp(13),dp(13));voice.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x22000000),Ui.shape(service,Ui.SURFACE,14,true),null));voice.setContentDescription(I18n.text(service,"voice_goal"));voice.setTooltipText(I18n.text(service,"voice_input"));voice.setOnClickListener(v->{saveDraft();hidePanel();service.startActivity(new Intent(service,VoiceActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));});actions.addView(voice,new LinearLayout.LayoutParams(dp(50),dp(50)));panel.addView(actions);Ui.gap(panel,10);continueRun=Ui.button(service,I18n.text(service,"continue_goal"),true,()->{close();service.continueGoal();});continueRun.setVisibility(service.limitReached?View.VISIBLE:View.GONE);panel.addView(continueRun,new LinearLayout.LayoutParams(-1,dp(50)));Ui.gap(panel,20);
  LinearLayout progress=Ui.column(service);progress.setPadding(dp(14),dp(14),dp(14),dp(14));progress.setBackground(Ui.shape(service,Ui.FIELD,16,true));Ui.label(progress,"SESSION");detail=Ui.text(service,"",12,Ui.MUTED,false);detail.setText((service.paused?I18n.text(service,"paused"):service.limitReached?I18n.text(service,"limit_reached"):I18n.text(service,"idle"))+" • Step "+service.step+"\n"+service.usage()+"\n"+AgentService.status.split("\n")[0]);progress.addView(detail);panel.addView(progress);Ui.gap(panel,14);
  LinearLayout controls=new LinearLayout(service);ImageButton pause=pauseRun=icon("ic_pause",I18n.text(service,"pause"),()->service.pauseGoal(I18n.text(service,"pause_menu")));ImageButton resume=resumeRun=icon("ic_play",I18n.text(service,"resume"),service::resumeGoal);LinearLayout.LayoutParams left=new LinearLayout.LayoutParams(0,dp(48),1);left.rightMargin=dp(8);controls.addView(pause,left);controls.addView(resume,new LinearLayout.LayoutParams(0,dp(48),1));panel.addView(controls);Ui.gap(panel,10);add(I18n.text(service,"control_center"),()->{close();service.startActivity(new Intent(service,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP));});
  surface=new ScrollView(service);surface.setBackground(Ui.shape(service,0xfaffffff,28,true));surface.setClipToOutline(true);surface.setVerticalScrollBarEnabled(false);surface.addView(panel);surface.setElevation(dp(12));int maxHeight=wm.getCurrentWindowMetrics().getBounds().height()-dp(120);panel.measure(View.MeasureSpec.makeMeasureSpec(Math.min(dp(340),wm.getCurrentWindowMetrics().getBounds().width()-dp(24)),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));
  WindowManager.LayoutParams p=new WindowManager.LayoutParams(Math.min(dp(340),wm.getCurrentWindowMetrics().getBounds().width()-dp(24)),Math.min(panel.getMeasuredHeight(),maxHeight),WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,PixelFormat.TRANSLUCENT);p.gravity=Gravity.CENTER;p.softInputMode=WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE;wm.addView(surface,p);
 }
 void add(String text,Runnable action){panel.addView(Ui.button(service,text,false,action),new LinearLayout.LayoutParams(-1,dp(48)));}
 ImageButton icon(String resource,String label,Runnable action){ImageButton b=new ImageButton(service);b.setImageResource(service.getResources().getIdentifier(resource,"drawable",service.getPackageName()));b.setScaleType(ImageView.ScaleType.CENTER_INSIDE);b.setPadding(dp(12),dp(12),dp(12),dp(12));b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x22000000),Ui.shape(service,Ui.SURFACE,14,true),null));b.setContentDescription(label);b.setTooltipText(label);b.setOnClickListener(v->action.run());return b;}
 void conceal(){concealed=true;ticker.setVisibility(View.INVISIBLE);if(surface!=null){surface.setVisibility(View.INVISIBLE);WindowManager.LayoutParams p=(WindowManager.LayoutParams)surface.getLayoutParams();p.flags|=WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE;wm.updateViewLayout(surface,p);((android.view.inputmethod.InputMethodManager)service.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(surface.getWindowToken(),0);}}
 void reveal(){if(destroyed)return;concealed=false;bubble.setVisibility(View.VISIBLE);if(surface!=null){WindowManager.LayoutParams p=(WindowManager.LayoutParams)surface.getLayoutParams();p.flags&=~(WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE);wm.updateViewLayout(surface,p);surface.setVisibility(View.VISIBLE);}}
 void saveDraft(){if(input!=null)GoalSettings.goal(service,input.getText().toString());}
 void hidePanel(){if(surface!=null){wm.removeView(surface);surface=null;}panel=null;detail=null;input=null;continueRun=null;pauseRun=null;resumeRun=null;}
 void close(){saveDraft();hidePanel();}
 void voiceResult(String text,String error){if(destroyed)return;if(text!=null){GoalSettings.goal(service,text);}else service.log(error);open();}
 void destroy(){destroyed=true;handler.removeCallbacks(refresh);close();wm.removeView(bubble);wm.removeView(ticker);}
}
